(window.__qhadithX=window.__qhadithX||{})[26]={"214":[{"c":"Al-Adab Al-Mufrad","r":"Book 2, Hadith 48","u":"https://quranx.com/Hadith/Adab/English/Book-2/Hadith-48","x":"Abu Hurayra said, \"When the following ayat was revealed ('Warn your near relatives' (26:214)), the Prophet, may Allah bless him and grant him peace, stood up and called out, saying, 'Banu Ka'b ibn Lu'ayy! Save yourselves from the Fire! Banu 'Abdu Manaf! Save yourselves from the Fire! Banu Hashim! Save yourselves from the Fire! Banu 'Abdu'l-Muttalib! Save yourselves from the Fire! Fatima, daughter of Muhammad! Save yourselves from the Fire! I do not have anything for you in respect to Allah except for the fact that you have ties of kinship.'\"","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، قَالَ‏:‏ حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنْ مُوسَى بْنِ طَلْحَةَ، عَنْ أَبِي هُرَيْرَةَ قَالَ‏:‏ لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ قَامَ النَّبِيُّ صلى الله عليه وسلم فَنَادَى‏:‏ يَا بَنِي كَعْبِ بْنِ لُؤَيٍّ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ‏.‏ يَا بَنِي عَبْدِ مَنَافٍ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ‏.‏ يَا بَنِي هَاشِمٍ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ‏.‏ يَا بَنِي عَبْدِ الْمُطَّلِبِ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ‏.‏ يَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ، أَنْقِذِي نَفْسَكِ مِنَ النَّارِ، فَإِنِّي لاَ أَمْلِكُ لَكِ مِنَ اللهِ شَيْئًا، غَيْرَ أَنَّ لَكُمْ رَحِمًا سَأَبُلُّهُمَا بِبِلاَلِهَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2752","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2752","x":"Narrated Anas:\n\nThe Prophet (ﷺ) said to Abu Talha, \"I recommend that you divide (this garden) amongst your relatives.\" Abu Talha said, \"O Allah's Messenger (ﷺ)! I will do the same.\" So Abu Talha divided it among his relatives and cousins. Ibn 'Abbes said, \"When the Qur'anic Verse: \"Warn your nearest kinsmen.\" (26.214) Was revealed, the Prophet (ﷺ) started calling the various big families of Quraish, \"O Bani Fihr! O Bani Adi!\". Abu Huraira said, \"When the Verse: \"Warn your nearest kinsmen\" was revealed, the Prophet (ﷺ) said (in a loud voice), \"O people of Quraish!\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا مَالِكٌ، عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ، أَنَّهُ سَمِعَ أَنَسًا ـ رضى الله عنه ـ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم لأَبِي طَلْحَةَ ‏\"‏ أَرَى أَنْ تَجْعَلَهَا فِي الأَقْرَبِينَ ‏\"‏‏.‏ قَالَ أَبُو طَلْحَةَ أَفْعَلُ يَا رَسُولَ اللَّهِ‏.‏ فَقَسَمَهَا أَبُو طَلْحَةَ فِي أَقَارِبِهِ وَبَنِي عَمِّهِ‏.‏ وَقَالَ ابْنُ عَبَّاسٍ لَمَّا نَزَلَتْ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ جَعَلَ النَّبِيُّ صلى الله عليه وسلم يُنَادِي ‏\"‏ يَا بَنِي فِهْرٍ، يَا بَنِي عَدِيٍّ ‏\"‏‏.‏ لِبُطُونِ قُرَيْشٍ‏.‏ وَقَالَ أَبُو هُرَيْرَةَ لَمَّا نَزَلَتْ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ يَا مَعْشَرَ قُرَيْشٍ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2753","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2753","x":"Narrated Abu Huraira:\n\nWhen Allah revealed the Verse: \"Warn your nearest kinsmen,\" Allah's Messenger (ﷺ) got up and said, \"O people of Quraish (or said similar words)! Buy (i.e. save) yourselves (from the Hellfire) as I cannot save you from Allah's Punishment; O Bani `Abd Manaf! I cannot save you from Allah's Punishment, O Safiya, the Aunt of Allah's Messenger (ﷺ)! I cannot save you from Allah's Punishment; O Fatima bint Muhammad! Ask me anything from my wealth, but I cannot save you from Allah's Punishment.\"","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ أَنَّ أَبَا هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ ‏}‏ قَالَ ‏\"‏ يَا مَعْشَرَ قُرَيْشٍ ـ أَوْ كَلِمَةً نَحْوَهَا ـ اشْتَرُوا أَنْفُسَكُمْ، لاَ أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئًا، يَا بَنِي عَبْدِ مَنَافٍ لاَ أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئًا، يَا عَبَّاسُ بْنَ عَبْدِ الْمُطَّلِبِ لاَ أُغْنِي عَنْكَ مِنَ اللَّهِ شَيْئًا، وَيَا صَفِيَّةُ عَمَّةَ رَسُولِ اللَّهِ لاَ أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئًا، وَيَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ سَلِينِي مَا شِئْتِ مِنْ مَالِي لاَ أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئًا ‏\"‏‏.‏ تَابَعَهُ أَصْبَغُ عَنِ ابْنِ وَهْبٍ عَنْ يُونُسَ عَنِ ابْنِ شِهَابٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3525","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3525","x":"Narrated Ibn `Abbas:\n\nWhen the Verse:-- 'And warn your tribe of near kindred.' (26.214) was revealed, the Prophet (ﷺ) started calling (the 'Arab tribes), \"O Bani Fihr, O Bani `Adi\" mentioning first the various branch tribes of Quraish.","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا عَمْرُو بْنُ مُرَّةَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ لَمَّا نَزَلَتْ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ جَعَلَ النَّبِيُّ صلى الله عليه وسلم يُنَادِي ‏\"‏ يَا بَنِي فِهْرٍ، يَا بَنِي عَدِيٍّ لِبُطُونِ قُرَيْشٍ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3526","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3526","x":"Narrated Ibn `Abbas:\n\nWhen the Verse:-- 'And warn your tribe of near kindred' (26.214). was revealed, the Prophet (ﷺ) started calling every tribe by its name.","ar":"وَقَالَ لَنَا قَبِيصَةُ أَخْبَرَنَا سُفْيَانُ، عَنْ حَبِيبِ بْنِ أَبِي ثَابِتٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَمَّا نَزَلَتْ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ جَعَلَ النَّبِيُّ صلى الله عليه وسلم يَدْعُوهُمْ قَبَائِلَ قَبَائِلَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4771","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4771","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) got up when the Verse:--'And warn your tribe of near kindred....\" (26.214) was revealed and said, \"O Quraish people! (or he said a similar word) Buy yourselves! I cannot save you from Allah (if you disobey Him) O Bani Abu Manaf! I cannot save you from Allah (if you disobey Him). O `Abbas! The son of `Abdul Muttalib! I cannot save you from Allah (if you disobey Him) O Safiya, (the aunt of Allah's Messenger (ﷺ)) I cannot save you from Allah (if you disobey Him). O Fatima, the daughter of Muhammad ! Ask what you wish from my property, but I cannot save you from Allah (if you disobey Him).","ar":"حَدَّثَنَا أَبُو الْيَمَانِ، أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ أَنَّ أَبَا هُرَيْرَةَ، قَالَ قَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ أَنْزَلَ اللَّهُ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ قَالَ ‏\"‏ يَا مَعْشَرَ قُرَيْشٍ ـ أَوْ كَلِمَةً نَحْوَهَا ـ اشْتَرُوا أَنْفُسَكُمْ، لاَ أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئًا، يَا بَنِي عَبْدِ مَنَافٍ، لاَ أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئًا، يَا عَبَّاسُ بْنَ عَبْدِ الْمُطَّلِبِ، لاَ أُغْنِي عَنْكَ مِنَ اللَّهِ شَيْئًا، وَيَا صَفِيَّةُ عَمَّةَ رَسُولِ اللَّهِ، لاَ أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئًا وَيَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ سَلِينِي مَا شِئْتِ مِنْ مَالِي، لاَ أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئًا ‏\"‏‏.‏ تَابَعَهُ أَصْبَغُ عَنِ ابْنِ وَهْبٍ عَنْ يُونُسَ عَنِ ابْنِ شِهَابٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4971","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4971","x":"Narrated Ibn `Abbas:\n\nWhen the Verse:-- 'And warn your tribe of near kindred.' (26.214) was revealed. Allah's Messenger (ﷺ) went out, and when he had ascended As-Safa mountain, he shouted, \"O Sabahah!\" The people said, \"Who is that?\" \"Then they gathered around him, whereupon he said, \"Do you see? If I inform you that cavalrymen are proceeding up the side of this mountain, will you believe me?\" They said, \"We have never heard you telling a lie.\" Then he said, \"I am a plain warner to you of a coming severe punishment.\" Abu Lahab said, \"May you perish! You gathered us only for this reason? \" Then Abu Lahab went away. So the \"Surat:--ul--LAHAB\" 'Perish the hands of Abu Lahab!' (111.1) was revealed.","ar":"حَدَّثَنَا يُوسُفُ بْنُ مُوسَى، حَدَّثَنَا أَبُو أُسَامَةَ، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا عَمْرُو بْنُ مُرَّةَ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ لَمَّا نَزَلَتْ ‏{‏وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ وَرَهْطَكَ مِنْهُمُ الْمُخْلَصِينَ، خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم حَتَّى صَعِدَ الصَّفَا فَهَتَفَ ‏\"‏ يَا صَبَاحَاهْ ‏\"‏‏.‏ فَقَالُوا مَنْ هَذَا، فَاجْتَمَعُوا إِلَيْهِ‏.‏ فَقَالَ ‏\"‏ أَرَأَيْتُمْ إِنْ أَخْبَرْتُكُمْ أَنَّ خَيْلاً تَخْرُجُ مِنْ سَفْحِ هَذَا الْجَبَلِ أَكُنْتُمْ مُصَدِّقِيَّ ‏\"‏‏.‏ قَالُوا مَا جَرَّبْنَا عَلَيْكَ كَذِبًا‏.‏ قَالَ ‏\"‏ فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ ‏\"‏‏.‏ قَالَ أَبُو لَهَبٍ تَبًّا لَكَ مَا جَمَعْتَنَا إِلاَّ لِهَذَا ثُمَّ قَامَ فَنَزَلَتْ ‏{‏تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ‏}‏ وَقَدْ تَبَّ هَكَذَا قَرَأَهَا الأَعْمَشُ يَوْمَئِذٍ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 204a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-204a","x":"Abu Huraira reported:\n\nWhen this verse was revealed:\" And warn thy nearest kindred (al-Qur'an, xxvi. 214), the Messenger of Allah (ﷺ) called the Quraish; so they gathered and he gave them a general warning. Then he made a particular (reference to certain tribes) and said: O sons of Ka'b b. Luwayy, rescue yourselves from the Fire; O sons of Murra b. Ka'b, rescue yourselves from the Fire: O sons of Abd Shams, rescue yourselves from the Fire; 0 sons of Abd Manaf rescue yourselves from the Fire; O sons of Hashim, rescue yourselves from the Fire; 0 sons of Abd al-Muttalib, rescue yourselves from the Fire; O Fatimah, rescue thyself from the Fire, for I have no power (to protect you) from Allah in anything except this that I would sustain relationship with you.","ar":"حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، وَزُهَيْرُ بْنُ حَرْبٍ، قَالاَ حَدَّثَنَا جَرِيرٌ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنْ مُوسَى بْنِ طَلْحَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا أُنْزِلَتْ هَذِهِ الآيَةُ ‏{‏ وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ‏}‏ دَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم قُرَيْشًا فَاجْتَمَعُوا فَعَمَّ وَخَصَّ فَقَالَ ‏\"‏ يَا بَنِي كَعْبِ بْنِ لُؤَىٍّ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ يَا بَنِي مُرَّةَ بْنِ كَعْبٍ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ يَا بَنِي عَبْدِ شَمْسٍ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ يَا بَنِي عَبْدِ مَنَافٍ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ يَا بَنِي هَاشِمٍ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ يَا بَنِي عَبْدِ الْمُطَّلِبِ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ يَا فَاطِمَةُ أَنْقِذِي نَفْسَكِ مِنَ النَّارِ فَإِنِّي لاَ أَمْلِكُ لَكُمْ مِنَ اللَّهِ شَيْئًا غَيْرَ أَنَّ لَكُمْ رَحِمًا سَأَبُلُّهَا بِبَلاَلِهَا ‏\"‏ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 329","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-329","x":"Abu Hurairah (May Allah be pleased with him) reported:\n\nWhen this Verse was revealed: \"And warn your tribe (O Muhammad (ﷺ)) of near kindred\". (26:214) Messenger of Allah (ﷺ) called the Quraish; when they gathered, he said to them: \"O sons of 'Abd Shams; O sons of Ka'b bin Lu'ai, rescue yourselves from the Fire! O sons of Murrah bin Ka'b, rescue yourselves from the Fire! O sons of 'Abd Manaf, rescue yourselves from the Fire! O sons of 'Abdul-Muttalib, rescue yourselves from the Fire! O Fatimah, rescue yourself from the Fire, for I have no power (to protect you) from Allah in anything except that I would sustain relationship with you\".[Muslim].","ar":"وعن أبي هريرة رضي الله عنه قال‏:‏ لما نزلت هذه الآية‏:‏ ‏(‏وأنذر عشيرتك الأقربين‏)‏ ‏(‏‏(‏الشعراء‏:‏ 214‏)‏‏)‏ دعا رسول الله صلى الله عليه وسلم قريشًا، فاجتمعوا فعم، وخص وقال‏:‏ ‏\n\n\"‏يا بني عبد شمس، يا بني كعب بن لؤي، أنقذوا أنفسكم من النار، يا بني مرة بن كعب، أنقذوا أنفسكم من النار، يا بني عبد مناف، أنقذوا أنفسكم من النار، يا بني هاشم أنقذوا أنفسكم من النار، يا بني عبد المطلب أنقذوا أنفسكم من النار، يا فاطمة أنقذي نفسك من النار، فإني لا أملك لكم من الله شيئًا، غير أن لكم رحما سأبلها ببلالها‏\"\n\n‏ ‏(‏‏(‏رواه مسلم‏)‏‏)‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 4, Book 34, Hadith 2310","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-4/Book-34/Hadith-2310","x":"'Aishah narrated:\n\n\"When this Ayah was revealed: And warn your near kindred....(26:214), the Messenger of Allah (s.a.w) said: \"O Safiyyah bint 'Abdul-Muttalib! O Fatimah bint Muhammed! O Banu 'Abdul-Muttalib! I have no authority on your behalf over Allah for anything. Ask me for whatever you want of my wealth.\"","ar":"حَدَّثَنَا أَبُو الأَشْعَثِ، أَحْمَدُ بْنُ الْمِقْدَامِ الْعِجْلِيُّ حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏ وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ ‏)‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا صَفِيَّةُ بِنْتَ عَبْدِ الْمُطَّلِبِ يَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ يَا بَنِي عَبْدِ الْمُطَّلِبِ إِنِّي لاَ أَمْلِكُ لَكُمْ مِنَ اللَّهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُمْ ‏\"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ أَبِي هُرَيْرَةَ وَأَبِي مُوسَى وَابْنِ عَبَّاسٍ ‏.‏ قَالَ حَدِيثُ عَائِشَةَ حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ هَكَذَا رَوَى بَعْضُهُمْ عَنْ هِشَامِ بْنِ عُرْوَةَ نَحْوَ هَذَا وَرَوَى بَعْضُهُمْ عَنْ هِشَامٍ عَنْ أَبِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم مُرْسَلاً لَمْ يَذْكُرْ فِيهِ عَنْ عَائِشَةَ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3184","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3184","x":"Narrated 'Aishah:\n\n\"When this Ayah was revealed: 'And warn your tribe of near kindred (26:214).' The Messenger of Allah (ﷺ) said: 'O Safiyyah bint 'Abdul-Muttalib! O Fatimah bint Muhammad! O Banu 'Abdul-Muttalib! I have no power to help you at all before Allah! Ask of me whatever you want from my wealth.'\"","ar":"حَدَّثَنَا أَبُو الأَشْعَثِ، أَحْمَدُ بْنُ الْمِقْدَامِ الْعِجْلِيُّ حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ لَمَّا نَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏وأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ ‏)‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا صَفِيَّةُ بِنْتَ عَبْدِ الْمُطَّلِبِ يَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ يَا بَنِي عَبْدِ الْمُطَّلِبِ إِنِّي لاَ أَمْلِكُ لَكُمْ مِنَ اللَّهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُمْ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَهَكَذَا رَوَى وَكِيعٌ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ هِشَامِ بْنِ عُرْوَةَ عَنْ أَبِيهِ عَنْ عَائِشَةَ نَحْوَ حَدِيثِ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ الطُّفَاوِيِّ ‏.‏ رَوَى بَعْضُهُمْ عَنْ هِشَامِ بْنِ عُرْوَةَ عَنْ أَبِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم مُرْسَلاً وَلَمْ يَذْكُرْ فِيهِ عَنْ عَائِشَةَ ‏.‏ وَفِي الْبَابِ عَنْ عَلِيٍّ وَابْنِ عَبَّاسٍ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3185","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3185","x":"Narrated Abu Hurairah:\n\n\"When (the following) was revealed: 'And warn your tribe of near kindred (26:214)' the Messenger of Allah (ﷺ) gathered the (families) of the Quraish (calling them) one and all, he said: 'O people of the Quraish! Ransom yourselves from the Fire! I have no power to prevent harm or bring benefit to you before Allah! O people of Banu 'Abd Manaf! Ransom yourselves from the Fire! I have no power to prevent harm or bring benefit to you before Allah! O people of Banu Qusayy! Ransom yourselves from the Fire! I have no power to prevent harm or bring benefit to you! O people of Banu 'Abdul-Muttalib! Ransom yourselves from the Fire! I have no power to prevent harm or bring benefit to you! O Fatimah bint Muhammad! Ransom yourself from the Fire! I have no power to prevent harm or bring benefit to you before Allah! All you have is the womb, and the kind relations that shall come of it.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا زَكَرِيَّا بْنُ عَدِيٍّ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عَمْرٍو الرَّقِّيُّ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنْ مُوسَى بْنِ طَلْحَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا نَزَلَتْ ‏:‏ ‏(‏ وأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ ‏)‏ جَمَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم قُرَيْشًا فَخَصَّ وَعَمَّ فَقَالَ ‏\"‏ يَا مَعْشَرَ قُرَيْشٍ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ فَإِنِّي لاَ أَمْلِكُ لَكُمْ مِنَ اللَّهِ ضَرًّا وَلاَ نَفْعًا يَا مَعْشَرَ بَنِي عَبْدِ مَنَافٍ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ فَإِنِّي لاَ أَمْلِكُ لَكُمْ مِنَ اللَّهِ ضَرًّا وَلاَ نَفْعًا يَا مَعْشَرَ بَنِي قُصَىٍّ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ فَإِنِّي لاَ أَمْلِكُ لَكُمْ ضَرًّا وَلاَ نَفْعًا يَا مَعْشَرَ بَنِي عَبْدِ الْمُطَّلِبِ أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ فَإِنِّي لاَ أَمْلِكُ لَكُمْ ضَرًّا وَلاَ نَفْعًا يَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ أَنْقِذِي نَفْسَكِ مِنَ النَّارِ فَإِنِّي لاَ أَمْلِكُ لَكِ ضَرًّا وَلاَ نَفْعًا إِنَّ لَكِ رَحِمًا سَأَبُلُّهَا بِبِلاَلِهَا ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ يُعْرَفُ مِنْ حَدِيثِ مُوسَى بْنِ طَلْحَةَ ‏.‏ حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، حَدَّثَنَا شُعَيْبُ بْنُ صَفْوَانَ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، عَنْ مُوسَى بْنِ طَلْحَةَ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ بِمَعْنَاهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3186","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3186","x":"Narrated Qasamah bin Zuhair:\n\n\"Al-Ash'ari said: 'When (the following) was revealed: 'And warn your tribe of near kindred (26:214)' the Messenger of Allah (ﷺ) placed his fingers in his ears, raised his voice and said: 'O Banu 'Abd Manaf! Hearken!'\"","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ أَبِي زِيَادٍ، حَدَّثَنَا أَبُو زَيْدٍ، عَنْ عَوْفٍ، عَنْ قَسَامَةَ بْنِ زُهَيْرٍ، حَدَّثَنَا الأَشْعَرِيُّ، قَالَ لَمَّا نَزَلََ ‏:‏ ‏(‏وأنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ ‏)‏ وَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَصْبُعَيْهِ فِي أُذُنَيْهِ فَرَفَعَ مِنْ صَوْتِهِ فَقَالَ ‏\"‏ يَا بَنِي عَبْدِ مَنَافٍ يَا صَبَاحَاهُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ مِنْ هَذَا الْوَجْهِ مِنْ حَدِيثِ أَبِي مُوسَى ‏.‏ وَقَدْ رَوَاهُ بَعْضُهُمْ عَنْ عَوْفٍ عَنْ قَسَامَةَ بْنِ زُهَيْرٍ عَنِ النَّبِيِّ صلى الله عليه وسلم مُرْسَلاً وَلَمْ يَذْكُرُوا فِيهِ عَنْ أَبِي مُوسَى وَهُوَ أَصَحُّ ذَاكَرْتُ بِهِ مُحَمَّدَ بْنَ إِسْمَاعِيلَ فَلَمْ يَعْرِفْهُ مِنْ حَدِيثِ أَبِي مُوسَى ‏.‏","v":[]}],"223":[{"c":"Al-Adab Al-Mufrad","r":"Book 36, Hadith 871","u":"https://quranx.com/Hadith/Adab/English/Book-36/Hadith-871","x":"In respect of \"And as for the poets, is the misled who follow them. Do you not see how they ramble on in every style and that they say things which they do not do?\" (26:223-225), Ibn 'Abbas said that it was abrogated and that an exception was made in His words, \"except for those who believe and do right actions the kind of reversal they will receive.\" (26:226)","ar":"حَدَّثَنَا إِسْحَاقُ، قَالَ‏:‏ أَخْبَرَنَا عَلِيُّ بْنُ الْحُسَيْنِ قَالَ‏:‏ حَدَّثَنِي أَبِي، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ‏:‏ ‏{‏وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏وَأَنَّهُمْ يَقُولُونَ مَا لاَ يَفْعَلُونَ‏}‏، فَنَسَخَ مِنْ ذَلِكَ وَاسْتَثْنَى فَقَالَ‏:‏ ‏{‏إِلاَّ الَّذِينَ آمَنُوا‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏يَنْقَلِبُونَ‏}‏‏.‏","v":[]}],"224":[{"c":"Sunan Abu Dawud","r":"Hadith 5034","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-5034","x":"Narrated AbuHurayrah:\n\nRespond three times to your brother when he sneezes, and if he sneezes more often, he has a cold in his head.","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنِ ابْنِ عَجْلاَنَ، قَالَ حَدَّثَنِي سَعِيدُ بْنُ أَبِي سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ شَمِّتْ أَخَاكَ ثَلاَثًا فَمَا زَادَ فَهُوَ زُكَامٌ ‏.‏","v":[]},{"c":"Al-Adab Al-Mufrad","r":"Book 36, Hadith 871","u":"https://quranx.com/Hadith/Adab/English/Book-36/Hadith-871","x":"In respect of \"And as for the poets, is the misled who follow them. Do you not see how they ramble on in every style and that they say things which they do not do?\" (26:223-225), Ibn 'Abbas said that it was abrogated and that an exception was made in His words, \"except for those who believe and do right actions the kind of reversal they will receive.\" (26:226)","ar":"حَدَّثَنَا إِسْحَاقُ، قَالَ‏:‏ أَخْبَرَنَا عَلِيُّ بْنُ الْحُسَيْنِ قَالَ‏:‏ حَدَّثَنِي أَبِي، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ‏:‏ ‏{‏وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏وَأَنَّهُمْ يَقُولُونَ مَا لاَ يَفْعَلُونَ‏}‏، فَنَسَخَ مِنْ ذَلِكَ وَاسْتَثْنَى فَقَالَ‏:‏ ‏{‏إِلاَّ الَّذِينَ آمَنُوا‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏يَنْقَلِبُونَ‏}‏‏.‏","v":[]}],"225":[{"c":"Al-Adab Al-Mufrad","r":"Book 36, Hadith 871","u":"https://quranx.com/Hadith/Adab/English/Book-36/Hadith-871","x":"In respect of \"And as for the poets, is the misled who follow them. Do you not see how they ramble on in every style and that they say things which they do not do?\" (26:223-225), Ibn 'Abbas said that it was abrogated and that an exception was made in His words, \"except for those who believe and do right actions the kind of reversal they will receive.\" (26:226)","ar":"حَدَّثَنَا إِسْحَاقُ، قَالَ‏:‏ أَخْبَرَنَا عَلِيُّ بْنُ الْحُسَيْنِ قَالَ‏:‏ حَدَّثَنِي أَبِي، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ‏:‏ ‏{‏وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏وَأَنَّهُمْ يَقُولُونَ مَا لاَ يَفْعَلُونَ‏}‏، فَنَسَخَ مِنْ ذَلِكَ وَاسْتَثْنَى فَقَالَ‏:‏ ‏{‏إِلاَّ الَّذِينَ آمَنُوا‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏يَنْقَلِبُونَ‏}‏‏.‏","v":[]}],"226":[{"c":"Al-Adab Al-Mufrad","r":"Book 36, Hadith 871","u":"https://quranx.com/Hadith/Adab/English/Book-36/Hadith-871","x":"In respect of \"And as for the poets, is the misled who follow them. Do you not see how they ramble on in every style and that they say things which they do not do?\" (26:223-225), Ibn 'Abbas said that it was abrogated and that an exception was made in His words, \"except for those who believe and do right actions the kind of reversal they will receive.\" (26:226)","ar":"حَدَّثَنَا إِسْحَاقُ، قَالَ‏:‏ أَخْبَرَنَا عَلِيُّ بْنُ الْحُسَيْنِ قَالَ‏:‏ حَدَّثَنِي أَبِي، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ‏:‏ ‏{‏وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏وَأَنَّهُمْ يَقُولُونَ مَا لاَ يَفْعَلُونَ‏}‏، فَنَسَخَ مِنْ ذَلِكَ وَاسْتَثْنَى فَقَالَ‏:‏ ‏{‏إِلاَّ الَّذِينَ آمَنُوا‏}‏ إِلَى قَوْلِهِ‏:‏ ‏{‏يَنْقَلِبُونَ‏}‏‏.‏","v":[]}],"227":[{"c":"Sunan Abu Dawud","r":"Hadith 5034","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-5034","x":"Narrated AbuHurayrah:\n\nRespond three times to your brother when he sneezes, and if he sneezes more often, he has a cold in his head.","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنِ ابْنِ عَجْلاَنَ، قَالَ حَدَّثَنِي سَعِيدُ بْنُ أَبِي سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ شَمِّتْ أَخَاكَ ثَلاَثًا فَمَا زَادَ فَهُوَ زُكَامٌ ‏.‏","v":[]}]};